#!/usr/bin/env python3
"""Integrate the independently audited completed-unit and full-Prym results."""
from pathlib import Path
import datetime
import json
import subprocess

w = Path(__file__).resolve().parents[1]
stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%H:%M UTC')
records = {
    'A.159': {
        'answers': 'A5; A9; A15; L10; L14; L20',
        'depends_on': 'A.138 constant-field three-class vanishing; A.156 exact norm generator and residue characters; four literal integral units; Dirichlet unit rank; exact determinant-two residue detectors; split S-divisor sequence; actual Hilbert90 and conjugation maps',
        'uses_local_theorem': 'no',
        'manuscript_passages': 'cote149; scans56–58 and126–127; prescribed coherent norm seed and the actual fixed-support obstruction',
        'notes': 'Every completed S-unit preimage of beta1=1-alpha in the specified degree9 field fails the next completed field-norm condition. The four exact units are proved three-saturated by four residue characters of determinant2. The entire completed relative-unit kernel has zero repair characters. The actual S-divisor kernel is generated by h=beta1/beta2^3 with divisor P2-2P0 and trivial characters. The companion Hilbert90 calculation gives an actual C3² subgroup in Cl(K2(mu3)){3}, through the three-primary differences of conjugate ramified quadratic primes. All four units have literal integer-coordinate block tables in the paper, reconstructed and norm-checked independently by root. No conclusion about changing the first seed or enlarging support is inferred.',
        'detail': 'A.159 excludes the entire completed S-unit fibre over the specified first seed at the next norm step, and proves an explicit C3² subgroup in the associated CM class group. The unrestricted first seed remains under investigation.'
    },
    'A.160': {
        'answers': 'A1; A5; A10; A11; A15; L7; L10; L14',
        'depends_on': 'A.150 literal Prym map; A.152 reduced torsion fibres; A.154 exact two-primary Sha; A.157 actual cover and integral homology quotient; explicit CM-field scaling and quadratic trace maps; Burungale–Tian Theorem1.1; Rubin TheoremA; explicit Shapiro and Kummer maps; Stoll Theorem8.2 with errata; Stix neighbourhood criterion and Harari–Stix torsor comparison',
        'uses_local_theorem': 'no; the domain throughout is full Selmer sections or the explicitly locally matching quotient sections',
        'manuscript_passages': 'cote149; scans56–58; precise section packets on the harmonic cover and one combined Kummer class of the tripod',
        'notes': 'The full Sha(E_b/Q(sqrt2)) is finite. Exact scaling over Q(sqrt2,i) produces C/Q(i); two explicit quadratic trace pairs transfer the A154 two-primary finiteness to the two CM curves, so the p=2 analytic converse and Rubin full-Sha theorem apply with every hypothesis checked. The odd-order subgroup is not computed. Res_(K/Q)E_b has exactly two rational points and finite Sha by explicit global/local Shapiro. Its adjunction map has the four boundary points as the two reduced rational fibres. All finite Kummer sequences force every finite local centre into one fibre. The compact section-neighbourhood pro-point, with its decomposition image equal to s(G_Q), gives the actual global point or cusp packet. This classifies full Selmer sections of every hyperbolic open of Dbar over Q and K=Q(sqrt2); D-open sections and tripod sections in the specified combined mod8 class are cuspidal. The all-coefficient proper-abelian quotient Rhat⋊C8 excludes ordinary localization at every finite prime for locally matching sections. Both principal A1 assertions remain open outside this stated class.',
        'detail': 'A.160 proves full Prym Sha finiteness by an exact CM descent and classifies full Selmer sections on the harmonic cover over Q and Q(sqrt2). Every full Selmer tripod section in the specified combined mod8 class is cuspidal; its all-coefficient metabelian comparison has no ordinary finite localization. This is a specified-class result, and both general A1 assertions remain open.'
    }
}

inputs = [
    'two_inert_seed_sunit_obstruction_agent.tex',
    'two_inert_class_corollary_agent.tex',
    'two_inert_unit_coefficients_supplement.tex',
    'harmonic_prym_full_sha.tex'
]
p = w/'SECTIONS_OVER_Q_paper.tex'
s = p.read_text()
anchor = r'\input{sections/harmonic_prym_finite_depth.tex}'
assert anchor in s
assert all((w/'sections'/name).exists() for name in inputs)
if not any(name in s for name in inputs):
    s = s.replace(anchor, anchor+'\n'+'\n'.join(r'\input{sections/'+name+'}' for name in inputs), 1)
else:
    assert all(name in s for name in inputs)
p.write_text(s)

p = w/'notes/register_metadata.json'
metadata = json.loads(p.read_text())
for ident, row in records.items():
    metadata[ident] = {k:v for k,v in row.items() if k != 'detail'}
p.write_text(json.dumps(metadata, indent=2, ensure_ascii=False)+'\n')

p = w/'SECTIONS_OVER_Q_references.bib'
bib = p.read_text()
newbib = (w/'notes/harmonic_prym_cm_references.bib').read_text()
keys = ['LegBurungaleTian2026', 'LegRubin1987CM']
if not any('{'+key+',' in bib for key in keys):
    p.write_text(bib.rstrip()+'\n\n'+newbib.rstrip()+'\n')
else:
    assert all('{'+key+',' in bib for key in keys)

p = w/'SECTIONS_OVER_Q_report.md'
lines = p.read_text().splitlines()
assert lines[0] == 'INCOMPLETE'
for i, line in enumerate(lines[:55]):
    if not line.startswith('| '):
        continue
    cells = [x.strip() for x in line.strip().strip('|').split('|')]
    if len(cells) != 3:
        continue
    for ident, rec in records.items():
        if cells[0] in {x.strip() for x in rec['answers'].split(';')}:
            if ident not in cells[1]:
                cells[1] += ', '+ident
            if rec['detail'] not in cells[2]:
                cells[2] += ' '+rec['detail']
    lines[i] = '| '+' | '.join(cells)+' |'
heading = '## Continued work: the complete fixed-seed obstruction and global cuspidality of the harmonic class'
if heading not in lines:
    lines.extend(['', heading, '', stamp+': '+records['A.159']['detail']+' '+records['A.160']['detail'], '',
        'The completed norm obstruction now controls every S-unit modification of the displayed second element. Four explicit integral units and four residue detectors prove saturation at three without a regulator or class-number completeness assertion. The local S-divisor calculation removes the only additional norm-zero direction, generated by beta1/beta2^3. The companion class argument inserts the precise extended fractional ideal before applying sigma(v)/v, then descends by u tau(u). It yields two independent order-three ideal classes. A literal coefficient supplement supplies every unit coordinate in integral elements, and an independent table-first program reconstructs all coefficients and verifies their exact relative norms.',
        'For the harmonic Prym, the CM descent uses delta=2(1+i) and k=(1+i+sqrt2)/(2(1+i)), with epsilon=delta*k² and b=9168*i*M²*k^4. The two quadratic trace/twist maps have both compositions [2]. The exact A154 two-primary result therefore gives finite 2-infinity Selmer groups over the CM field for both required curves. The opened Burungale–Tian theorem applies at2, and the first assertion of Rubin TheoremA gives full Sha finiteness. Restriction, corestriction and the second twist pair prove the assertion for the original Prym. No analytic rank is guessed and no order of the odd Sha subgroup is asserted.',
        'The adjunction map to Res_(Q(sqrt2)/Q)E_b retains the actual two reduced boundary fibres. Its compatible finite Selmer classes are the Kummer classes of one rational torsion point, because full Sha is finite. Full local Kummer injectivity holds at every finite physical prime. For each section-neighbourhood, Harari–Stix descent and Stoll finite support supply a rational point over the fixed boundary scheme; compactness produces a compatible rational pro-point. The decomposition image inside the actual section subgroup projects onto the full absolute Galois group and hence equals the section subgroup. This proves an actual cusp packet. The same argument over Q(sqrt2) uses the original Prym map. The all-coefficient proper-homology quotient gives the stated every-finite-place restriction for locally matching metabelian sections.',
        'Every principal classification or birational-lifting scope not covered by these exact assertions remains on the open list. The changed-first-seed calculation is a separate continuation and is not an assertion of an infinite fixed-support norm family.', ''])
p.write_text('\n'.join(lines)+'\n')

audit = (stamp+' A159/A160 integrated after root and independent audits. A159 literal two-block unit tables reconstructed and all exact relative norms checked; the S-unit kernel and class C3² comparison passed. A160 original BT/Rubin hypotheses, integral trace maps, Shapiro, full Kummer comparisons, reduced fibres, and the corrected section-neighbourhood decomposition argument passed. Stoll8.2/errata3 and Stix2.1.2–3/Cor5 reopened. Full Selmer scope and both open A1 assertions retained.\n')
for name in ['notes/hour12_root_audits.md','notes/root_progress.md']:
    with (w/name).open('a') as f:
        f.write('\n'+audit)
proc = subprocess.run(['python',str(w/'code/build_register.py')], capture_output=True, text=True, check=True)
out = 'Integrated audited A159 and A160, their exact supplements, and two verified primary references.\n'+proc.stdout
Path(__file__).with_name('integrate_a159_a160_output.txt').write_text(out)
print(out, end='')
